def solve(lst):
    out = []
    stack = [iter(lst)]
    while stack:
        it = stack[-1]
        try:
            x = next(it)
        except StopIteration:
            stack.pop()
            continue
        if isinstance(x, list):
            stack.append(iter(x))
        else:
            out.append(x)
    return out
